void ForEachPiece(ulong b) {
    while (b != 0) {
        int sq = math.tzcnt(b);                      // клетка младшей фигуры; .NET: BitOperations.TrailingZeroCount
        int x = sq & 7, y = sq >> 3;
        b &= b - 1;                                  // Керниган: снять её
    }
}

