int Mask4(int x, int y) {                    // N = 1, E = 2, S = 4, W = 8
    int m = 0;
    if (Wall(x, y + 1)) m |= 1;
    if (Wall(x + 1, y)) m |= 2;
    if (Wall(x, y - 1)) m |= 4;
    if (Wall(x - 1, y)) m |= 8;
    return m;                                // индекс тайла 0..15
}
